-- Verify all hashes are valid 12-char hex strings
DO $$
DECLARE
  invalid_count INT;
BEGIN
  SELECT COUNT(*) INTO invalid_count
  FROM tool_classification_cache
  WHERE LENGTH(tool_description_hash) != 12
     OR tool_description_hash !~ '^[a-f0-9]{12}$';

  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'Found % tools with invalid hashes', invalid_count;
  END IF;
END $$;
